      assert.equal(fs.existsSync(path.join(repo, "pwned")), false);
      controller.send({ type: "approve", id, always: false });
      await server.idle();
      assert.equal(fs.readFileSync(path.join(repo, "x.txt"), "utf8"), "hi", "approve once still works");
